<template>
  <div
    class="col-sm-12 col-md-12 col-lg-12"
    @click.capture="onCardClickCapture"
  >
    <q-card
      class="card-margin-bottom"
      :class="notEvaluated ? 'cursor-not-allowed opacity-half' : 'cursor-pointer'"
      bordered
      flat
    >
      <div class="float-right q-ml-auto q-pa-xs">
        <div class="float-right">
          <template v-if="card_result">
            <q-icon name="check_circle" size="22px" color="green"></q-icon>
          </template>
          <template v-else>
            <div v-if="item.card_logs && !item.card_logs[0]">
              <q-icon name="block" size="22px" color="black"></q-icon>
            </div>
            <div
              v-else-if="item.card_logs && item.card_logs[0] && item.card_logs[0].card_result && item.card_logs[0].card_result == 'failed_condition'">
              <q-icon name="do_not_disturb_on" size="22px" color="orange"></q-icon>
            </div>
            <div v-else>
              <q-icon name="cancel" size="22px" color="red"></q-icon>
            </div>
          </template>
        </div>
        <div class="completion-time-margin">
          {{ item.completion_time }}
        </div>
      </div>
      <q-card-section class="row no-padding">

        <div class="col-1 card-svg-margin" round flat size="xs" :style="'background-color:' + color">
          <i v-html="item.svg" class="svg-icon center-inner "></i>
        </div>

        <q-card-section class="col-11">
          <div class="color-93939A paddingMargin0 font-size-0-75">
            {{ $t(item.category) }}
          </div>
          <p class="paddingMargin0 font-size-15 card-text">
            <template v-if="!dataArray || dataArray.length < 1">
              {{ cardPlainText }}
            </template>

            <template v-else>
              <template v-for='(str, index) in dataArray' :key='index'>
                <template v-if="renderBadge(str)">
                  {{ $t(getVariableData(str)) != invalid ? $t(getVariableData(str)) : getVariableData(str) }}
                </template>
                <template v-else-if="renderTextTranslation(str)">
                  {{ $t(str) != invalid ? $t(str) : str }}
                </template>
                <template v-else>
                  {{ str + ' ' }}
                </template>
              </template>
            </template>

          </p>
        </q-card-section>
      </q-card-section>
    </q-card>
  </div>
</template>

<script lang="ts">

import { defineComponent, ref } from 'vue';
import helperUtil from 'src/utils/helperUtil';
import helperMixin from 'src/mixins/helperMixin';
import { workflowSplitDelimiter, workflowTranslationDelimiter, invalid } from 'src/constants';
import { dynamicObj } from 'src/pages/assets';
import { useWorkflowLogsVariablesStore } from 'src/store/WorkflowBuilder/workflow_logs_variables.store';
import { useDropdownStore } from 'src/store/main';
import { storeToRefs } from 'pinia';
import { getVariableData as gcfgetVariableData, prepareData as gcfprepareData, resolveCardPlainText } from 'src/pages/WorkflowBuilder/generic_card_functions';

export default defineComponent({
  name: 'generic-card',
  emits: [],
  mixins: [helperUtil, helperMixin],
  components: {},
  props: {
    isDialog: {
      type: Boolean,
      default: false,
    },
    itemIndex: {
      type: Number,
      default: null,
    },
    cardType: {
      type: String,
      default: '',
    },
    parentSvg: {
      type: String,
      default: '',
    },
    color: {
      type: String,
      default: '',
    },
    card_result: {
      type: Boolean,
      default: false,
    },
    item: {
      type: Object,
      default: {
        category: '',
        id: '',
        text: '',
        toolTip: '',
        card_version: '',
      } as any,
    }
  },
  data() {
    return {
      showItemPanel: ref(false),
      dataArray: ref([] as string[]),
    };
  },

  computed: {
    cardPlainText(): string {
      return resolveCardPlainText(this.item);
    },
    notEvaluated(): boolean {
      const logs = (this.item as any)?.card_logs;
      return !this.card_result && Array.isArray(logs) && !logs[0];
    },
  },

  mounted() {
    this.prepareDataForVariableReplacement();
    this.prepareData();
  },
  // unmounted: function () {
  //   logInfo('unmounted');
  // },

  methods: {


    renderBadge(str: string) {
      return str.startsWith(workflowSplitDelimiter);
    },

    renderTextTranslation(str: string) {
      return str.startsWith(workflowTranslationDelimiter);
    },

    getVariableData(var_id: string) {
      return this.item ? gcfgetVariableData(var_id, this.item, this.data) : ''
    },

    prepareDataForVariableReplacement() {
      this.data.users = this.users;
      this.data.groups = this.groups;
      this.data.workflows = this.workflows;
      this.data.decision_tables = this.decision_tables;
      this.data.subOrgList = this.subOrgList;
      this.data.prompts = this.doc_operator_prompts;
      this.data.email_templates = this.email_template_list;
    },

    prepareData() {
      this.dataArray = gcfprepareData(this.item as dynamicObj)

    },

    onCardClickCapture(e: MouseEvent) {
      if (this.notEvaluated) {
        e.stopImmediatePropagation();
        e.preventDefault();
      }
    },

  },
  setup() {

    const useWorkflowStore = useWorkflowLogsVariablesStore()
    const { users, groups, workflows, decision_tables, doc_operator_prompts } = storeToRefs(useWorkflowStore)
    const dropdown_store = useDropdownStore();
    const { resetSubOrgsList } = dropdown_store;
    const { subOrgList, email_template_list } = storeToRefs(dropdown_store);

    return {
      users,
      groups,
      workflows,
      data: {} as dynamicObj,
      decision_tables,
      resetSubOrgsList,
      subOrgList,
      doc_operator_prompts,
      email_template_list,
    }
  },
});
</script>

